// Read-only demo mode (build with VITE_DEMO=1, see README "Demo build").
// Every API call is answered from static JSON files in public/demo-data/
// (generated by scripts/make-demo-data.py), so the demo needs no backend:
// browsing, search, filters and paging work; any change is refused.

export const DEMO = import.meta.env.VITE_DEMO === '1'
export const DEMO_USER = 'demo'
export const DEMO_PASSWORD = 'demo'
export const DEMO_READ_ONLY = 'This is a demo — changes are disabled.'

const cache = new Map()
async function file(name) {
  if (!cache.has(name)) {
    cache.set(name, fetch(`${import.meta.env.BASE_URL}demo-data/${name}.json`).then(r => {
      if (!r.ok) throw new Error(`demo data ${name}: ${r.status}`)
      return r.json()
    }))
  }
  return cache.get(name)
}

/** Answers one API request like the backend would. Throws { status, detail }. */
export async function demoRequest(path, method) {
  const url = new URL(path, 'http://demo.local')
  const p = url.pathname
  const q = url.searchParams

  if (method === 'POST' && p === '/admin/login') {
    const expires = new Date(Date.now() + 7 * 24 * 3600 * 1000).toISOString()
    return { token: 'demo', expires_at: expires, username: DEMO_USER }
  }
  if (method !== 'GET') throw { status: 403, detail: DEMO_READ_ONLY }

  if (p === '/admin/me') return { username: DEMO_USER }
  if (p === '/admin/stats') return file('stats')
  if (p === '/admin/coverage') return file('coverage')
  if (p === '/admin/words') {
    const target = q.get('target')
    const all = await file('words')
    return target ? all.filter(w => w.lang === target) : all
  }
  if (p.startsWith('/admin/words/')) {
    const id = decodeURIComponent(p.slice('/admin/words/'.length))
    const w = (await file('words')).find(x => x.external_id === id)
    if (!w) throw { status: 404, detail: 'Word not found' }
    return w
  }
  if (p === '/admin/devices') {
    const term = (q.get('q') || '').trim().toLowerCase()
    const limit = Number(q.get('limit') || 50)
    const offset = Number(q.get('offset') || 0)
    const all = (await file('devices')).filter(d => !term || d.device_id.toLowerCase().includes(term))
    return { total: all.length, items: all.slice(offset, offset + limit) }
  }
  if (p === '/admin/word-issues') {
    const status = q.get('status')
    const all = await file('word-issues')
    return status ? all.filter(i => i.status === status) : all
  }
  throw { status: 404, detail: 'Not available in the demo' }
}
